import{_ as o,l,o as e,c as s,v as t,p as n,x as i,d as R,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const G=JSON.parse('{"title":"iBGP 与路由反射器","description":"","frontmatter":{"title":"iBGP 与路由反射器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ibgp-route-reflector.md","filePath":"cs/ibgp-route-reflector.md","lastUpdated":1789023840000}'),c={name:"cs/ibgp-route-reflector.md"};function P(B,a,h,_,u,f){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="ibgp-与路由反射器" tabindex="-1">iBGP 与路由反射器 <a class="header-anchor" href="#ibgp-与路由反射器" aria-label="Permalink to &quot;iBGP 与路由反射器&quot;">​</a></h1><div class="epigraph"><p>iBGP 学来的路由默认不再转给其它 iBGP 对等，于是要全网状；路由反射器把网状收成星形，用簇 ID 防环。</p><footer>—— 据 RFC 4271 iBGP 再通告规则；RFC 4456 BGP Route Reflection 整理</footer></div><p><a href="/cs/bgp-attributes-decision">上一课</a> 选出最佳路径。AS 内部如何把这条路径告诉所有边界路由器？缺口是 <strong>iBGP 全网状问题</strong>与 <strong>RR</strong>：不是再讲 LOCAL_PREF，而是通告范围。本课不把抖动抑制写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若 iBGP 允许再通告，AS_PATH 不变，环难查。规则：iBGP 学到的不转给 iBGP。于是 \\(n\\) 台边界要 \\(n(n-1)/2\\) 会话。RR：客户把路由发给反射器，反射器按规则转给其它客户与非客户，Cluster-List / Originator-ID 防反射环。联盟（RFC 5065）是另一刀，把 AS 切成子 AS。</p><p>不要把 RR 当成 OSPF ABR：IGP 仍要全可达下一跳；RR 只减 BGP 会话。</p><p><span class="marginnote">RFC 4456。下一跳原样保留（除非 next-hop-self）。本课不把 add-path 在 RR 上的部署写完。</span></p><h3 id="rr-不是-abr" tabindex="-1">RR 不是 ABR <a class="header-anchor" href="#rr-不是-abr" aria-label="Permalink to &quot;RR 不是 ABR&quot;">​</a></h3><p>iBGP 再通告规则逼出全网状或反射。RR 减会话，数据面仍跟 IGP。只反射最佳会藏备选出口。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：全网状 vs RR 星形 vs 两台 RR 冗余。对照 L2：生成树也是减环，但是转发树；RR 是控制面会话树，数据面仍按 IGP 走。</p>',11)),(e(),n(d,null,{default:i(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20C1%5B%22iBGP%20%E5%AE%A2%E6%88%B7%22%5D%20--%3E%20RR%5B%22%E8%B7%AF%E7%94%B1%E5%8F%8D%E5%B0%84%E5%99%A8%22%5D%0A%20%20C2%5B%22iBGP%20%E5%AE%A2%E6%88%B7%22%5D%20--%3E%20RR%0A%20%20RR%20--%3E%20C1%0A%20%20RR%20--%3E%20C2%0A%20%20CL%5B%22Cluster-List%22%5D%20--%3E%20LOOP%5B%22%E9%98%B2%E5%8F%8D%E5%B0%84%E7%8E%AF%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[R(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>决策在每台路由器独立做：RR 若只反射最佳，客户可能看不见备选，热土豆/冷土豆与出口选择会变形——这是 RR 的正确性边界。与 MAC 洪泛不同：这里不洪泛数据包。骨干 IS-IS 提供下一跳可达，BGP 提供前缀。</p><p>next-hop-self 常在 RR 或 ASBR 改写下一跳到自己，避免外部下一跳在区内不可达。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 BGP Confederations 的全部属性改写。BGP 收敛与抖动抑制是下一课。后课默认：iBGP 不全网状就要 RR 或联盟。</p><p>单 RR 是控制面单点；成对 RR 要注意簇设计，避免分区时环。</p><p>上一课留下的缺口在本课收口；「iBGP 与路由反射器」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/bgp-convergence-dampening">BGP 收敛与抖动抑制</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>iBGP 不把学来的路由再给 iBGP，故需网状或 RR。</li><li>RR 用簇与 Originator 防环，可能藏备选路径。</li><li>数据面仍跟 IGP 下一跳。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4271；RFC 4456。</li></ul>',10))])}const b=o(c,[["render",P]]);export{G as __pageData,b as default};
